import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // ---------------------------------------------------------------------
  // Quote -- simplest case
  // ---------------------------------------------------------------------
  it.todo("quotes an empty item list as 5 G (processing fee only)");

  // ---------------------------------------------------------------------
  // Quote -- main item base premiums (price-list catalogue, premium side)
  // Each entry is independent data and gets its own test.
  // ---------------------------------------------------------------------
  it.todo("quotes a single plain sword as 105 G (100 G base + 5 G fee)");
  it.todo("quotes a single plain amulet as 65 G (60 G base + 5 G fee)");
  it.todo("quotes a single plain staff as 85 G (80 G base + 5 G fee)");
  it.todo("quotes a single plain potion as 45 G (40 G base + 5 G fee)");

  // ---------------------------------------------------------------------
  // Quote -- component base premiums and the building block of 3 alike
  // ---------------------------------------------------------------------
  it.todo("quotes a single rune as 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as 30 G (25 G base + 5 G fee)");
  it.todo("quotes 2 runes as 55 G (50 G base, no block + 5 G fee)");
  it.todo("quotes 3 runes as 65 G (60 G block base + 5 G fee)");
  it.todo("quotes 4 runes as 105 G (100 G base, block requires exactly 3 + 5 G fee)");
  it.todo("quotes 7 runes as 180 G (175 G base, no block for 7 + 5 G fee)");
  it.todo(
    "quotes 2 runes + 1 moonstone as 80 G (75 G base, no block: alike means same type + 5 G fee)",
  );
  it.todo(
    "quotes 3 runes + 3 moonstones as 125 G (120 G base, two separate blocks + 5 G fee)",
  );

  // ---------------------------------------------------------------------
  // Quote -- item-scoped modifiers and their thresholds
  // ---------------------------------------------------------------------
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium (cursed sword -> 155 G)");
  it.todo(
    "adds a 30 % high-enchantment surcharge at exactly enchantment 5 (sword ench 5 -> 135 G)",
  );
  it.todo("adds no high-enchantment surcharge at enchantment 4 (sword ench 4 -> 105 G)");
  it.todo(
    "applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 -> 185 G",
  );

  // ---------------------------------------------------------------------
  // Quote -- modifier scope on multi-item policies
  // ---------------------------------------------------------------------
  it.todo(
    "applies the curse surcharge only to the cursed item's base premium, not the policy total (cursed sword + plain amulet -> 215 G)",
  );

  // ---------------------------------------------------------------------
  // Quote -- policy-scoped modifiers and their thresholds
  // ---------------------------------------------------------------------
  it.todo(
    "applies a 20 % loyalty discount on the policy base premium at exactly 2 years with MHPCO (sword -> 85 G)",
  );
  it.todo("applies no loyalty discount at 1 year with MHPCO (sword -> 105 G)");
  it.todo(
    "applies a 10 % first-insurance surcharge per insured item (newcomer with a cursed sword -> 165 G)",
  );
  it.todo(
    "applies a 15 % follow-up-contract discount on every quote after the customer's first (second quote of a plain sword, 0 years -> 100 G)",
  );
  it.todo(
    "still applies the first-insurance surcharge on a follow-up contract (3 years, second quote, cursed sword ench 7 -> 160 G)",
  );

  // ---------------------------------------------------------------------
  // Quote -- rounding in the MHPCO's favour
  // ---------------------------------------------------------------------
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favour)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // ---------------------------------------------------------------------
  // Quote -- rejection
  // ---------------------------------------------------------------------
  it.todo(
    "throws an Error when a quote contains an item of unknown type (e.g. broomstick) -- chosen contract: domain throws Error, CLI exits non-zero with stderr message",
  );

  // ---------------------------------------------------------------------
  // Claim -- standard reimbursement and the per-damage deductible
  // ---------------------------------------------------------------------
  it.todo(
    "pays out damage minus the 100 G deductible for a plain steel sword ench 3, damage 500 G -> payout 400 G",
  );
  it.todo(
    "pays out damage minus the 100 G deductible for a rune (no enchantment, no material), damage 200 G -> payout 100 G",
  );
  it.todo(
    "applies the 100 G deductible once per damaged item (sword 500 G + amulet 300 G -> payout 600 G)",
  );

  // ---------------------------------------------------------------------
  // Claim -- special clauses and their thresholds
  // ---------------------------------------------------------------------
  it.todo(
    "reimburses 50 % of the damage at exactly enchantment 8 (steel sword, damage 1000 G -> payout 400 G)",
  );
  it.todo(
    "applies no high-enchantment clause at enchantment 7 (steel sword, damage 1000 G -> payout 900 G)",
  );
  it.todo(
    "reimburses dragon material fully (dragon sword ench 5, damage 800 G -> payout 700 G)",
  );
  it.todo(
    "lets the 50 % high-enchantment rule win over dragon material (dragon sword ench 9, damage 1000 G -> payout 400 G)",
  );
  it.todo(
    "applies the high-enchantment clause alone for a steel sword ench 9, damage 1000 G -> payout 400 G",
  );
  it.todo(
    "applies the high-enchantment clause then the deductible for a dragon sword at exactly ench 8, damage 1000 G -> payout 400 G",
  );

  // ---------------------------------------------------------------------
  // Claim -- rounding in the MHPCO's favour
  // ---------------------------------------------------------------------
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favour)");

  // ---------------------------------------------------------------------
  // Claim -- insurance sum and cap (price-list catalogue, insurance-value
  // side; each item type's insurance value is independent data)
  // ---------------------------------------------------------------------
  it.todo("caps a sword policy at 2000 G (2 x 1000 G insurance value)");
  it.todo("caps an amulet policy at 1200 G (2 x 600 G insurance value)");
  it.todo("caps a staff policy at 1600 G (2 x 800 G insurance value)");
  it.todo("caps a potion policy at 800 G (2 x 400 G insurance value)");
  it.todo("caps a single-rune policy at 500 G (2 x 250 G insurance value)");
  it.todo("caps a single-moonstone policy at 500 G (2 x 250 G insurance value)");
  it.todo(
    "sums insurance values across items for the cap (sword + amulet -> insurance sum 1600 G, cap 3200 G)",
  );
  it.todo(
    "bases the cap on unmodified insurance values (cursed sword, premium 165 G -> cap still 2000 G)",
  );
  it.todo(
    "ignores the block discount for the insurance sum (sword + 3 runes -> insurance sum 1750 G, cap 3500 G)",
  );

  // ---------------------------------------------------------------------
  // Claim -- cap exhaustion across successive claims
  // ---------------------------------------------------------------------
  it.todo(
    "reports the remaining cap after a claim (sword, cap 2000 G, claim 1500 G -> payout 1400 G, remainingCap 600 G)",
  );
  it.todo(
    "reduces a later payout to the remaining cap (second claim of 1500 G -> payout 600 G, remainingCap 0 G)",
  );

  // ---------------------------------------------------------------------
  // Claim -- multiple items of the same type
  // ---------------------------------------------------------------------
  it.todo(
    "insures two swords as insurance sum 2000 G with cap 4000 G",
  );
  it.todo(
    "treats two sword damage entries as separate damages, each with its own deductible (500 G + 300 G -> payout 600 G)",
  );

  // ---------------------------------------------------------------------
  // Claim -- rejection
  // ---------------------------------------------------------------------
  it.todo(
    "throws an Error when a damage names an item type not covered by the policy (amulet damaged, only a sword insured)",
  );
  it.todo(
    "throws an Error when a damage names an item of unknown type (e.g. broomstick)",
  );
  it.todo(
    "throws an Error when damages contain more entries of a type than the policy covers (two sword damages, one sword insured)",
  );
  it.todo("throws an Error when a damage amount is negative (amount: -200)");

  // ---------------------------------------------------------------------
  // Scenario processing -- steps, ordering and policy references
  // ---------------------------------------------------------------------
  it.todo("returns one result per step, in the order of the input steps");
  it.todo(
    "resolves a claim's policy field as the zero-based index of the quote step that created the policy",
  );
});

describe("claim-office CLI", () => {
  it.todo(
    "reads a scenario from stdin and writes {results: [...]} as JSON to stdout (schema example -> premium 65 G, payout 100 G, remainingCap 1100 G)",
  );
  it.todo(
    "exits with a non-zero status and writes an error description to stderr for an unknown item type, writing no results to stdout",
  );
  it.todo(
    "exits with a non-zero status and writes an error description to stderr for a damage outside the policy",
  );
  it.todo(
    "exits with a non-zero status and writes an error description to stderr for a negative damage amount",
  );
});

