export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function basePremiumOf(item: Item): number {
  return BASE_PREMIUMS[item.type];
}

function premiumFor(items: Item[]): number {
  const policyBasePremium = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): StepResult[] {
  return scenario.steps.map((step) => ({ premium: premiumFor(step.items) }));
}

