1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	const CURSE_SURCHARGE_RATE = 0.5;
54	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
55	const HIGH_ENCHANTMENT_LEVEL = 5;
56	const LOYALTY_DISCOUNT_RATE = 0.2;
57	const LOYALTY_YEARS = 2;
58	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
59	const DEDUCTIBLE = 100;
60	const CAP_MULTIPLE = 2;
61	
62	const BASE_PREMIUMS: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	const INSURANCE_VALUES: Record<string, number> = {
72	  sword: 1000,
73	};
74	
75	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
76	const COMPONENT_BLOCK_SIZE = 3;
77	const COMPONENT_BLOCK_PREMIUM = 60;
78	
79	/** The MHPCO insures only the items on its price list. */
80	function basePremiumForType(type: string): number {
81	  const basePremium = BASE_PREMIUMS[type];
82	  if (basePremium === undefined) {
83	    throw new Error(`The MHPCO does not insure items of type "${type}"`);
84	  }
85	  return basePremium;
86	}
87	
88	function basePremiumOf(item: Item): number {
89	  return basePremiumForType(item.type);
90	}
91	
92	function isComponent(item: Item): boolean {
93	  return COMPONENT_TYPES.has(item.type);
94	}
95	
96	function countByType(items: Item[]): Map<string, number> {
97	  const counts = new Map<string, number>();
98	  for (const item of items) {
99	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
100	  }
101	  return counts;
102	}
103	
104	/** A building block of exactly 3 alike components is offered at a special rate. */
105	function componentsBasePremium(components: Item[]): number {
106	  let total = 0;
107	  for (const [type, count] of countByType(components)) {
108	    total +=
109	      count === COMPONENT_BLOCK_SIZE
110	        ? COMPONENT_BLOCK_PREMIUM
111	        : count * basePremiumForType(type);
112	  }
113	  return total;
114	}
115	
116	function policyBasePremiumOf(items: Item[]): number {
117	  const components = items.filter(isComponent);
118	  const mainItems = items.filter((item) => !isComponent(item));
119	
120	  return (
121	    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
122	    componentsBasePremium(components)
123	  );
124	}
125	
126	function isCursed(item: Item): boolean {
127	  return item.cursed === true;
128	}
129	
130	function isHighlyEnchanted(item: Item): boolean {
131	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
132	}
133	
134	const RISK_SURCHARGE_RATES: readonly [(item: Item) => boolean, number][] = [
135	  [isCursed, CURSE_SURCHARGE_RATE],
136	  [isHighlyEnchanted, HIGH_ENCHANTMENT_SURCHARGE_RATE],
137	];
138	
139	/** Item-specific risk surcharges apply to the base premium of the affected item. */
140	function riskSurchargesFor(items: Item[]): number {
141	  return items.reduce((total, item) => {
142	    const rate = RISK_SURCHARGE_RATES.reduce(
143	      (sum, [applies, surchargeRate]) => sum + (applies(item) ? surchargeRate : 0),
144	      0,
145	    );
146	    return total + basePremiumOf(item) * rate;
147	  }, 0);
148	}
149	
150	function isLongStanding(customer: Customer): boolean {
151	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
152	}
153	
154	/** Policy-wide modifiers apply to the sum of all item base premiums. */
155	function policyModifierRateFor(customer: Customer, precedingContracts: number): number {
156	  const loyaltyDiscount = isLongStanding(customer) ? -LOYALTY_DISCOUNT_RATE : 0;
157	  const followUpDiscount = precedingContracts > 0 ? -FOLLOW_UP_DISCOUNT_RATE : 0;
158	
159	  return FIRST_INSURANCE_SURCHARGE_RATE + loyaltyDiscount + followUpDiscount;
160	}
161	
162	function premiumFor(items: Item[], customer: Customer, precedingContracts: number): number {
163	  const policyBasePremium = policyBasePremiumOf(items);
164	
165	  return Math.ceil(
166	    policyBasePremium +
167	      riskSurchargesFor(items) +
168	      policyBasePremium * policyModifierRateFor(customer, precedingContracts) +
169	      PROCESSING_FEE,
170	  );
171	}
172	
173	function insuranceValueForType(type: string): number {
174	  const insuranceValue = INSURANCE_VALUES[type];
175	  if (insuranceValue === undefined) {
176	    throw new Error(`The MHPCO does not insure items of type "${type}"`);
177	  }
178	  return insuranceValue;
179	}
180	
181	function insuranceSumOf(items: Item[]): number {
182	  return items.reduce((sum, item) => sum + insuranceValueForType(item.type), 0);
183	}
184	
185	interface Policy {
186	  items: Item[];
187	  remainingCap: number;
188	}
189	
190	/** A deductible applies per damage event. */
191	function payoutForDamage(damage: Damage): number {
192	  return Math.max(0, damage.amount - DEDUCTIBLE);
193	}
194	
195	function policyAt(policies: Map<number, Policy>, index: number): Policy {
196	  const policy = policies.get(index);
197	  if (policy === undefined) {
198	    throw new Error(`No policy was created by step ${index}`);
199	  }
200	  return policy;
201	}
202	
203	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
204	  const desiredPayout = incident.damages.reduce(
205	    (total, damage) => total + payoutForDamage(damage),
206	    0,
207	  );
208	
209	  const payout = Math.floor(Math.min(desiredPayout, policy.remainingCap));
210	  policy.remainingCap -= payout;
211	
212	  return { payout, remainingCap: policy.remainingCap };
213	}
214	
215	export function runScenario(scenario: Scenario): StepResult[] {
216	  const policies = new Map<number, Policy>();
217	  let contractsSoFar = 0;
218	
219	  return scenario.steps.map((step, index) => {
220	    if (step.op === "claim") {
221	      return settleClaim(policyAt(policies, step.policy), step.incident);
222	    }
223	
224	    const premium = premiumFor(step.items, scenario.customer, contractsSoFar);
225	    contractsSoFar += 1;
226	    policies.set(index, {
227	      items: step.items,
228	      remainingCap: insuranceSumOf(step.items) * CAP_MULTIPLE,
229	    });
230	    return { premium };
231	  });
232	}

